        // Current selected package
        let selectedPackage = null;

        // Initialize the application
        document.addEventListener('DOMContentLoaded', function() {
            renderPackages();
            setupEventListeners();
          
            
            // Set minimum date to today
            const today = new Date().toISOString().split('T')[0];
            document.getElementById('departureDate').setAttribute('min', today);
        });

        // Render packages in the container
        function renderPackages() {
            const packagesContainer = document.getElementById('packagesContainer');
            
            travelPackages.forEach(pkg => {
                const packageCard = document.createElement('div');
                packageCard.className = 'package-card';
                packageCard.innerHTML = `
                    <div class="package-image">
                        <img src="${pkg.image}" alt="${pkg.destination}">
                    </div>
                    <div class="package-content">
                        <h3 class="package-destination">${pkg.destination}</h3>
                        <p class="package-details">${pkg.hotel} • ${pkg.flight} • ${pkg.duration}</p>
                        <div class="package-price">$${pkg.price} <span>per person</span></div>
                        <button class="select-package" data-id="${pkg.id}">Select Package</button>
                    </div>
                `;
                packagesContainer.appendChild(packageCard);
            });
        }

        // Set up event listeners
        function setupEventListeners() {
            // Package selection
            document.addEventListener('click', function(e) {
                if (e.target.classList.contains('select-package')) {
                    const packageId = parseInt(e.target.getAttribute('data-id'));
                    selectPackage(packageId);
                }
            });
            
            // Form submission
            document.getElementById('bookingForm').addEventListener('submit', function(e) {
                e.preventDefault();
                handleBooking();
            });
        }

        // Handle package selection
        function selectPackage(packageId) {
            selectedPackage = travelPackages.find(pkg => pkg.id === packageId);
            
            if (selectedPackage) {
                const selectedPackageInfo = document.getElementById('selectedPackageInfo');
                selectedPackageInfo.innerHTML = `
                    <div class="package-info-image">
                        <img src="${selectedPackage.image}" alt="${selectedPackage.destination}">
                    </div>
                    <div class="package-info-details">
                        <div class="package-info-destination">${selectedPackage.destination}</div>
                        <div class="package-details">${selectedPackage.hotel} • ${selectedPackage.flight} • ${selectedPackage.duration}</div>
                        <div class="package-info-price">$${selectedPackage.price} per person</div>
                    </div>
                `;
                
                // Scroll to booking form
                document.getElementById('booking-Form').scrollIntoView({ behavior: 'smooth' });
                        const existingBookings = JSON.parse(localStorage.getItem('SelectBookingsPackages')) || [];
                   existingBookings.push(selectedPackage);
                localStorage.setItem('SelectBookingsPackages', JSON.stringify(existingBookings));
            }
        }

        // Handle booking form submission
        function handleBooking() {
            if (!selectedPackage) {
                showNotification('Please select a package first', 'error');
                return;
            }
            
            const formData = {
                firstName: document.getElementById('firstName').value,
                lastName: document.getElementById('lastName').value,
                email: document.getElementById('email').value,
                phone: document.getElementById('phone').value,
                departureDate: document.getElementById('departureDate').value,
                travelers: document.getElementById('travelers').value,
                specialRequests: document.getElementById('specialRequests').value,
                package: selectedPackage
            };
            
            // Calculate total price
            const totalPrice = selectedPackage.price * parseInt(formData.travelers);
            
            // Create booking object
            const booking = {
                id: Date.now(), // Unique ID based on timestamp
                client: `${formData.firstName} ${formData.lastName}`,
                email: formData.email,
                phone: formData.phone,
                destination: selectedPackage.destination,
                departureDate: formData.departureDate,
                travelers: formData.travelers,
                totalPrice: totalPrice,
                bookingDate: new Date().toLocaleDateString(),
                specialRequests: formData.specialRequests
            };
        
            // Store booking
            storeBooking(booking);
            
            // Reset form and selection
            document.getElementById('bookingForm').reset();
            selectedPackage = null;
            document.getElementById('selectedPackageInfo').innerHTML = 
                '<div class="empty-bookings">No package selected yet. Please choose a package from above.</div>';
            
            // Show success message
            showNotification('Booking successful! Thank you for your reservation.', 'success');
        }

        // Store booking in localStorage
        function storeBooking(booking) {
            let bookings = JSON.parse(localStorage.getItem('travelBookings')) || [];
            bookings.push(booking);
            localStorage.setItem('travelBookings', JSON.stringify(bookings));
            
           
   
        }

        
        // Show notification
        function showNotification(message, type) {
            const notification = document.getElementById('notification');
            notification.textContent = message;
            notification.className = `notification ${type}`;
            
            // Hide notification after 3 seconds
            setTimeout(() => {
                notification.className = 'notification';
            }, 3000);
        }